package main

import "fmt"

type Player struct {
	Name  string
	Score int
}

func main() {
	players := []Player{{"Ana", 10}, {"Budi", 20}}
	for i := range players {
		p := players[i]
		p.Score += 5
	}
	fmt.Println(players) // harapan: [{Ana 15} {Budi 25}]
}

